/**
 * ONIQ Story DNA — the structural library, 1,000 entries.
 *
 * Owner directive 2026-08-27 (local story intelligence). This is
 * STRUCTURAL DNA: retrieved from and RECOMBINED into original stories.
 * It is not training text, not a plot bank, and not prose to reproduce —
 * the library's own generation rule says so and travels with it as
 * DNA_POLICY below.
 *
 * SHAPE, measured over the delivered library rather than assumed: eight
 * of its nineteen columns carry the SAME string on all 1,000 rows (the
 * inciting / escalation / midpoint / climax patterns, the character and
 * setting engines, the adaptation modes and the generation rule). Those
 * are house POLICY, not per-entry DNA, so they are stored ONCE. Keeping
 * them per row would have quadrupled this file and told a reader they
 * vary, which they do not. What genuinely varies is what each row holds:
 *
 *   genre               20 values, 50 entries each
 *   core_engine        581 values
 *   protagonist_need   171 values
 *   central_twist      876 values
 *   ending_family        7 values
 *   structure           10 values
 *   pacing               5 values
 *   default_duration     8 values
 *
 * Rows are tuples, not objects: 1,000 objects with eleven repeated keys
 * costs ~3x the bytes for no added meaning, and `decodeEntry` below is
 * the single place that names them.
 *
 * Server-side only. This module lives under supabase/functions so it can
 * never be bundled into the browser: which DNA a story draws on is a
 * server decision, exactly like the GPU, the price and the watermark.
 */

/** The library's constant fields — house policy, stored once. */
export const DNA_POLICY = {
  "inciting_pattern": "an ordinary situation is disrupted by a consequential anomaly, decision, person, discovery, or deadline",
  "escalation_pattern": "each attempt to solve the immediate problem creates a harder problem and raises personal stakes",
  "midpoint_pattern": "the protagonist learns that the apparent problem connects to a deeper personal or systemic truth",
  "climax_pattern": "the protagonist makes an irreversible choice that resolves the external conflict and reveals character",
  "character_engine": "goal + fear + contradiction + relationship pressure",
  "setting_engine": "choose a culturally specific setting appropriate to the user's request; never infer identity attributes not requested",
  "adaptation_modes": "story|audio_story|short_film|episode|feature",
  "generation_rule": "Use structural DNA and recombine it into an original story. Do not reproduce source-specific prose, scenes, dialogue, or protected expression."
} as const;

export type DnaEntry = {
  id: string;
  genre: string;
  title: string;
  coreEngine: string;
  protagonistNeed: string;
  centralTwist: string;
  endingFamily: string;
  structure: string;
  pacing: string;
  defaultDuration: string;
  referenceInspirations: string;
};

type Row = readonly [
  string, string, string, string, string, string,
  string, string, string, string, string,
];

/** The one place the tuple positions are given names. */
export function decodeEntry(row: Row): DnaEntry {
  return {
    id: row[0],
    genre: row[1],
    title: row[2],
    coreEngine: row[3],
    protagonistNeed: row[4],
    centralTwist: row[5],
    endingFamily: row[6],
    structure: row[7],
    pacing: row[8],
    defaultDuration: row[9],
    referenceInspirations: row[10],
  };
}

